        boolean reversing = found.status().equals("SETTLED") && to.equals("VOID");
        if (reversing) {
            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
                throw new BadRequestException("only a steward can void a settled claim");
            }
